def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if float(opp.get('budget', 0)) >= 200:
            rich_count += 1
        if float(opp.get('hp', 10)) <= 3 or int(opp.get('no_water_days', 0)) >= 2:
            desperate_count += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    if tight_supply:
        urgency += 2
    elif loose_supply:
        urgency -= 1

    urgency += min(2, desperate_count)

    if day >= 8 and hp < 6:
        urgency += 1

    if highest_prev >= 140:
        if urgency <= 1:
            bid = 18.0 if loose_supply else 24.0
        elif urgency == 2:
            bid = 58.0
        elif urgency == 3:
            bid = 92.0
        else:
            bid = 148.0
    else:
        if urgency <= 0:
            bid = 16.0 if loose_supply else 22.0
        elif urgency == 1:
            bid = max(28.0, avg_prev * 0.45)
        elif urgency == 2:
            bid = max(45.0, highest_prev + 2.0 if highest_prev > 0 else 52.0)
        elif urgency == 3:
            bid = max(72.0, highest_prev + 3.0 if highest_prev > 0 else 78.0)
        else:
            bid = max(105.0, highest_prev + 4.0 if highest_prev > 0 else 110.0)

    if rich_count >= 2 and tight_supply and urgency >= 3:
        bid = max(bid, 145.0)

    reserve = 0.0
    if hp > 4 and no_water == 0:
        reserve = 20.0
    elif hp > 2:
        reserve = 8.0

    max_affordable = max(0.0, budget - reserve)
    bid = min(bid, max_affordable)

    if urgency >= 4 and budget > 0:
        bid = max(bid, min(budget, 150.0))

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids and survival pressure
    prev_bids = []
    prev_info = []  # (oid, bid, hp_after, budget_after)
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                bid_f = float(bid)
            except Exception:
                continue
            prev_bids.append(bid_f)
            prev_info.append((oid, bid_f, prev.get('hp_after', None), prev.get('budget_after', None)))

    # Identify likely heavy bidder (Cindy-like): high yesterday bid and still alive
    heavy_bid = None
    if prev_bids:
        heavy_bid = max(prev_bids)

    # Supply pressure: fewer units implies higher chance of bidding wars
    # supply is in [15,25]; map to 0..2 buckets
    supply_bucket = int((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9) * 2)
    if supply_bucket < 0:
        supply_bucket = 0
    if supply_bucket > 2:
        supply_bucket = 2

    # Core strategy
    # If Cindy-like heavy bidder existed, match or slightly undercut only when we are at risk.
    risk = 0
    if hp <= 2:
        risk += 2
    if no_water_days >= 1:
        risk += 1
    if supply_bucket == 0:  # tight supply
        risk += 1

    # Baseline bid depends on risk
    if risk >= 2:
        target = DAILY_SALARY * 0.95
    elif risk == 1:
        target = DAILY_SALARY * 0.65
    else:
        target = DAILY_SALARY * 0.45

    # If heavy bidder was very high yesterday, increase target to avoid losing water.
    if heavy_bid is not None:
        if heavy_bid >= DAILY_SALARY * 1.6:  # ~>=144
            if risk >= 1:
                target = max(target, heavy_bid * 0.92)
            else:
                target = max(target, heavy_bid * 0.75)
        elif heavy_bid >= DAILY_SALARY * 0.9:  # ~>=81
            if risk >= 2:
                target = max(target, heavy_bid * 0.85)
            else:
                target = max(target, heavy_bid * 0.65)

    # Budget guardrails
    # Ensure we don't overspend when budget is low.
    if budget <= 0:
        return 0.0

    # Cap bid to avoid bankrupting early; still aim to secure water when at risk.
    # Use remaining budget fraction; more risk -> spend more.
    spend_frac = 0.35
    if risk >= 2:
        spend_frac = 0.85
    elif risk == 1:
        spend_frac = 0.60

    max_affordable = budget * spend_frac
    bid = min(max_affordable, target)

    # Minimum meaningful bid to compete
    min_bid = DAILY_SALARY * 0.25
    if bid < min_bid and risk >= 1:
        bid = min(budget, min_bid)

    # Final clamp
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
